    return (
      <DropdownMenu.Submenu key={id}>
        <DropdownMenu.SubmenuTrigger value={id} className="group/row">
          <div className="flex items-center gap-2 min-w-0">
            {renderColumnIcon(icon)}
            <LabelWithBreadcrumbs
