export interface CreateOptionMenuProps<TData> {
  column: Column<TData, 'option'>
  actions: DataTableFilterActions
  filter?: FilterModel<'option'>
  locale?: Locale
  strategy?: FilterStrategy
}

export interface CreateMultiOptionMenuProps<TData> {
  column: Column<TData, 'multiOption'>
  actions: DataTableFilterActions
  filter?: FilterModel<'multiOption'>
  locale?: Locale
  strategy?: FilterStrategy
}

export type CreateOptionMenuResult = CreateSelectableMenuResult
export type CreateMultiOptionMenuResult = CreateSelectableMenuResult

/**
 * Creates option menu nodes for filter values.
 * Returns CheckboxItemDef[] for use with the Data-First API.
 */
export function createOptionMenu<TData>({
  column,
  actions,
  filter,
  locale,
  strategy,
}: CreateOptionMenuProps<TData>): CreateOptionMenuResult {
  return createSelectableMenuInternal({
    column: column as unknown as Column<unknown, 'option'>,
    actions,
    filter,
    locale,
    strategy,
  })
}

/**
 * Creates multiOption menu nodes for filter values.
 * Returns CheckboxItemDef[] for use with the Data-First API.
 */
export function createMultiOptionMenu<TData>({
  column,
  actions,
  filter,
  locale,
  strategy,
}: CreateMultiOptionMenuProps<TData>): CreateMultiOptionMenuResult {
  return createSelectableMenuInternal({
    column: column as unknown as Column<unknown, 'multiOption'>,
    actions,
    filter,
    locale,
    strategy,
  })
}

/**
 * Unified function for creating selectable menu nodes.
 * Can be used when the column type is dynamically determined.
 */
export function createSelectableMenu<TData>(
  props: CreateOptionMenuProps<TData> | CreateMultiOptionMenuProps<TData>,
): CreateSelectableMenuResult {
  return createSelectableMenuInternal({
    column: props.column as unknown as Column<unknown, 'option'>,
    actions: props.actions,
    filter: props.filter,
    locale: props.locale,
    strategy: props.strategy,
  })
}

import type {
  Column,
  DataTableFilterActions,
  TextFilterOperator,
} from '@bazza-ui/filters'
import type { ItemDef } from '@bazza-ui/react/dropdown-menu'
import { createTextItemRenderer } from './text-item'

/**
 * Data structure for text filter menu items.
 * Used to display operator and value in the TextItem component.
 */
export interface TextFilterItemData {
  operator: TextFilterOperator
  values: string[]
}

/**
 * Creates text filter items based on the current search query.
 * This is called dynamically when the search changes.
 */
export function createTextFilterItems<TData>({
  query,
  column,
  actions,
}: {
  query: string
  column: Column<TData, 'text'>
  actions: DataTableFilterActions
}): ItemDef[] {
  // Only show items when there's a query
  if (!query?.trim()) {
    return []
  }

  const changeText = (value: string, operator: TextFilterOperator) => {
    actions.batch((tx) => {
      tx.setFilterValue(column, [String(value)])
      tx.setFilterOperator(column.id, operator)
    })
  }

  const containsData: TextFilterItemData = {
    operator: 'contains',
    values: [query],
  }

  const doesNotContainData: TextFilterItemData = {
    operator: 'does not contain',
    values: [query],
  }

  return [
    {
      kind: 'item' as const,
      id: `${column.id}-text-contains-${query}`,
      value: `contains ${query}`,
      keywords: [query],
      onSelect: () => {
        changeText(query, 'contains')
      },
      render: createTextItemRenderer(containsData),
    } satisfies ItemDef,
    {
      kind: 'item' as const,
      id: `${column.id}-text-does-not-contain-${query}`,
      value: `does not contain ${query}`,
      keywords: [query],
      onSelect: () => {
        changeText(query, 'does not contain')
      },
      render: createTextItemRenderer(doesNotContainData),
    } satisfies ItemDef,
  ]
}

